class Solution:
    def maxCount(self, m: int, n: int, ops: List[List[int]]) -> int:
        min_r = m
        min_c = n
        for r, c in ops:
            if r < min_r:
                min_r = r
            if c < min_c:
                min_c = c
        return min_r * min_c

class Solution {
public:
    int maxCount(int m, int n, vector<vector<int>>& ops) {
        int minR = m, minC = n;
        for (const auto& op : ops) {
            minR = min(minR, op[0]);
            minC = min(minC, op[1]);
        }
        return minR * minC;
    }
};

class Solution {
    public int maxCount(int m, int n, int[][] ops) {
        int minR = m, minC = n;
        for (int[] op : ops) {
            minR = Math.min(minR, op[0]);
            minC = Math.min(minC, op[1]);
        }
        return minR * minC;
    }
}

var maxCount = function(m, n, ops) {
    let minR = m, minC = n;
    for (const [r, c] of ops) {
        if (r < minR) minR = r;
        if (c < minC) minC = c;
    }
    return minR * minC;
};
